function makeFoundations(base: PlannedLesson, course: CourseContent): KnowledgeTopic[] {
  return course.steps.map((item, index) => ({
    id: `${base.id}-foundation-${index}`,
    group: base.category === 'system' ? 'infra' : 'training',
    title: item.title,
    summary: item.detail,
    formula: item.formula,
    points: [item.deep, item.pitfall, item.handsOn],
    refs: base.refs,
  }));
}

export function completePlannedLessons(planned: PlannedLesson[]): ReadyLesson[] {
  return planned.map((base) => {
    const course = content.find((item) => item.id === base.id);
    if (!course) {
      throw new Error(`Missing complete course content: ${base.id}`);
    }
    const graph = graphForLesson(base.id);
    const events = graphEvents(graph);
    if (events.length !== course.steps.length * 2) {
      throw new Error(`Course steps and event pairs do not match: ${base.id}`);
    }
    return {
      id: base.id,
      code: base.code,
      title: base.title,
      subtitle: base.subtitle,
      category: base.category,
      status: 'ready',
      summary: course.summary,
      phaseLabels: graph.phaseLabels,
      facts: [
        { label: t('学习阶段', 'Learning stage'), value: t(`Stage ${base.stage}`, `Stage ${base.stage}`) },
        { label: t('学习结构', 'Learning structure'), value: t(`${course.steps.length} 章 · 推导 / 数值例 / 代码 / 实验`, `${course.steps.length} chapters · derivation / examples / code / experiments`) },
        { label: t('实践产出', 'Hands-on deliverable'), value: base.deliverable },
        { label: t('参考来源', 'References'), value: t(`${base.refs.length} 个原始来源`, `${base.refs.length} primary references`) },
      ],
      steps: course.steps.map((item, index) => ({
        title: item.title,
        subtitle: item.subtitle,
        detail: item.detail,
        formula: item.formula,
        lastEvent: index * 2 + 1,
        deepDive: [item.detail, item.deep],
        ...advancedStep(base.id, index),
        pitfalls: [item.pitfall, t('优化或修改前后必须使用相同输入、指标和测量边界做对照。', 'Use identical inputs, metrics and measurement boundaries before and after every optimization or change.')],
        handsOn: item.handsOn,
        checkpoints: item.checks,
        references: base.refs,
      })),
      nodes: graph.nodes,
      edges: graphEdges(graph),
      events,
      principles: course.principles,
      resources: base.refs,
      ladder: course.steps.map((item, index) => ({
        level: index + 1,
        title: item.title,
        gain: item.handsOn,
      })),
      foundations: makeFoundations(base, course),
    };
  });
}
